clickhouse.users:


    default

        ::1
        127.0.0.1

    default


    {{- if .Values.clickhouse.config.users.existingSecret }}

    {{- else }}
    {{ .Values.clickhouse.config.users.appUserPassword }}
    {{- end }}

        {{- if .Values.clickhouse.config.clusterCidrs }}
        {{- range .Values.clickhouse.config.clusterCidrs }}
        {{ . }}
        {{- end }}
        {{- else }}
        10.0.0.0/8  
        {{- end }}
        .*\.svc\.cluster\.local$

    readonly
    default

        GRANT SHOW ON *.*
        GRANT SELECT ON system.*
        GRANT SELECT ON default.*


<{{ .Values.otel.clickhouseUser | default .Values.clickhouse.config.users.otelUserName }}>
    {{- if .Values.clickhouse.config.users.existingSecret }}

    {{- else }}
    {{ .Values.otel.clickhousePassword | default .Values.clickhouse.config.users.otelUserPassword }}
    {{- end }}

        {{- if .Values.clickhouse.config.clusterCidrs }}
        {{- range .Values.clickhouse.config.clusterCidrs }}
        {{ . }}
        {{- end }}
        {{- else }}
        10.0.0.0/8  
        {{- end }}
        .*\.svc\.cluster\.local$

    default
    default

        GRANT SELECT,INSERT,CREATE,SHOW ON default.*

</{{ .Values.otel.clickhouseUser | default .Values.clickhouse.config.users.otelUserName }}>
